@push('scripts')
<script>
(() => {
    const app=document.getElementById('driverApp'); if(!app)return;
    const menu=document.getElementById('driverMenu'),menuToggle=document.getElementById('driverMenuToggle');
    const showPage=(name)=>{document.querySelectorAll('[data-app-page]').forEach(page=>page.hidden=page.dataset.appPage!==name);document.querySelectorAll('.driver-nav [data-page]').forEach(button=>button.classList.toggle('is-active',button.dataset.page===name));menu.hidden=true;menuToggle.setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'smooth'});};
    document.querySelectorAll('[data-page]').forEach(button=>button.addEventListener('click',()=>showPage(button.dataset.page)));
    menuToggle.addEventListener('click',()=>{menu.hidden=!menu.hidden;menuToggle.setAttribute('aria-expanded',String(!menu.hidden));});
    document.addEventListener('click',(event)=>{if(!menu.contains(event.target)&&!menuToggle.contains(event.target))menu.hidden=true;});
    document.getElementById('refreshDriverApp').addEventListener('click',()=>location.reload());
    document.addEventListener('click',async event=>{const button=event.target.closest('[data-copy-address]');if(!button)return;try{await navigator.clipboard.writeText(button.dataset.copyAddress);button.textContent='Address copied';}catch(_){prompt('Copy delivery address:',button.dataset.copyAddress);}});
    const notice=document.getElementById('driverNotice'),showMessage=(text)=>{notice.textContent=text;notice.style.display='block';};
    const notifyButton=document.getElementById('enableDriverNotifications'),notificationsUrl=app.dataset.notificationsUrl;let notificationCursor=Number(app.dataset.notificationCursor||0),notificationCheckRunning=false;
    const enableNotifications=async()=>{if(!('Notification'in window))return showMessage('Order alerts will appear inside the app. Browser notifications are not supported here.');if(Notification.permission==='default')await Notification.requestPermission();showMessage(Notification.permission==='granted'?'Order notifications are enabled.':'Open the app to see new order alerts.');};
    notifyButton.addEventListener('click',enableNotifications);
    const checkOrderNotifications=async()=>{if(notificationCheckRunning)return;notificationCheckRunning=true;try{const response=await fetch(`${notificationsUrl}?after=${notificationCursor}`,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)return;const data=await response.json();if(data.cursor)notificationCursor=Number(data.cursor);if(data.notifications?.length){let added=0;const activePage=document.querySelector('[data-app-page="active"]');for(const notification of data.notifications){if(!activePage||!notification.card_html||activePage.querySelector(`[data-driver-order="${notification.order_id}"]`))continue;const template=document.createElement('template');template.innerHTML=notification.card_html.trim();const card=template.content.firstElementChild;if(!card)continue;const firstCard=activePage.querySelector('.driver-order');const emptyState=activePage.querySelector('.driver-empty');if(emptyState)emptyState.remove();if(firstCard)firstCard.before(card);else activePage.append(card);initializeStatusForm(card.querySelector('[data-status-form]'));added++;}if(added){const activeCount=activePage.querySelectorAll('.driver-order').length;const activeTotal=activePage.querySelector('[data-driver-active-total]');if(activeTotal)activeTotal.textContent=`${activeCount} orders`;document.querySelectorAll('[data-driver-active-count]').forEach(counter=>counter.textContent=activeCount);showPage('active');const newest=activePage.querySelector('.driver-order');if(newest)newest.open=true;}const latest=data.notifications[data.notifications.length-1];const title=`New order #${latest.order_id}`;showMessage(`${title} from ${latest.customer_name || 'customer'} received. Opening active deliveries...`);if('Notification'in window&&Notification.permission==='granted'){const registration=await navigator.serviceWorker?.ready.catch(()=>null);if(registration)await registration.showNotification(title,{body:`${latest.customer_name || 'Customer'} · ${latest.customer_mobile || ''}`,tag:`delivery-order-${latest.order_id}`,data:{url:location.pathname}});else new Notification(title,{body:`${latest.customer_name || 'Customer'} · ${latest.customer_mobile || ''}`});}}}catch(_){}finally{notificationCheckRunning=false;}};
    checkOrderNotifications();setInterval(checkOrderNotifications,4000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkOrderNotifications();});
    const share=document.getElementById('shareLocationButton'),heading=document.getElementById('locationHeading'),caption=document.getElementById('locationCaption'),endpoint=app.dataset.locationUrl,csrf=document.querySelector('meta[name="csrf-token"]')?.content;let watchId=null,lastSent=0,wakeLock=null;
    const send=async(position)=>{if(Date.now()-lastSent<4000)return;lastSent=Date.now();const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy})});if(response.status===410){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;heading.textContent='No active deliveries';share.disabled=true;return;}if(!response.ok)throw new Error('GPS location could not be shared. Check your connection.');const result=await response.json();heading.textContent=`Sharing LIVE · ${result.active_deliveries} active`;caption.textContent=`Updated ${new Date(result.updated_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;share.classList.add('is-live');share.innerHTML='<i class="fa-solid fa-location-dot"></i> Sharing';notice.style.display='none';};
    share.addEventListener('click',()=>{if(!navigator.geolocation)return showMessage('GPS is unavailable on this phone.');if(location.protocol!=='https:'&&location.hostname!=='localhost')return showMessage('GPS needs the secure HTTPS app link.');if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;wakeLock?.release().catch(()=>{});wakeLock=null;heading.textContent='Location sharing paused';share.classList.remove('is-live');share.innerHTML='<i class="fa-solid fa-location-crosshairs"></i> Share GPS';return;}heading.textContent='Requesting GPS permission…';if(navigator.wakeLock?.request)navigator.wakeLock.request('screen').then(lock=>wakeLock=lock).catch(()=>{});watchId=navigator.geolocation.watchPosition(position=>send(position).catch(error=>showMessage(error.message)),error=>{watchId=null;heading.textContent='Location sharing is off';showMessage(error.code===1?'Allow GPS in phone settings to share your location.':'Could not get a GPS fix. Try outdoors.');},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});});
    const initializeStatusForm=form=>{if(!form||form.dataset.initialized==='true')return;form.dataset.initialized='true';const select=form.querySelector('[name="status"]'),scanTools=form.querySelector('[data-scan-tools]'),scanInput=form.querySelector('[name="delivery_scan_code"]'),update=form.querySelector('[data-update-status]'),camera=form.querySelector('[data-camera]'),video=form.querySelector('video');let stream=null,scanning=false;const toggle=()=>{const delivering=select.value==='Delivered';scanTools.classList.toggle('is-visible',delivering);scanInput.required=delivering;update.classList.toggle('is-delivered',delivering);};select.addEventListener('change',toggle);toggle();form.addEventListener('submit',event=>{if(select.value==='Delivered'&&!scanInput.value.trim()){event.preventDefault();showMessage('Scan a parcel or product barcode before confirming delivery.');scanInput.focus();return;}scanning=false;stream?.getTracks().forEach(track=>track.stop());});camera.addEventListener('click',async()=>{if(!('BarcodeDetector'in window))return showMessage('Camera barcode scanning is not supported. Use a handheld scanner or enter the scan code.');try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});video.srcObject=stream;video.style.display='block';await video.play();scanning=true;const detector=new BarcodeDetector();const scan=async()=>{if(!scanning)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){scanInput.value=codes[0].rawValue;scanning=false;stream.getTracks().forEach(track=>track.stop());video.style.display='none';return;}}catch(_){}requestAnimationFrame(scan);};requestAnimationFrame(scan);}catch(_){showMessage('Camera permission is unavailable. Enter the scan code manually.');}});};
    document.querySelectorAll('[data-status-form]').forEach(initializeStatusForm);
    const install=document.getElementById('installDriverApp'),apple=/iphone|ipad|ipod/i.test(navigator.userAgent),installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;let installPrompt=null;if(installed)install.style.display='none';addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});install.addEventListener('click',async()=>{if(installPrompt){installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice?.outcome==='accepted')install.style.display='none';installPrompt=null;return;}showMessage(apple?'In Safari, tap Share then Add to Home Screen.':'In Chrome, tap ⋮ then Install app or Add to Home screen.');});
    if('serviceWorker'in navigator&&location.protocol==='https:'){navigator.serviceWorker.register('/driver-app-sw.js',{updateViaCache:'none'}).then(registration=>{registration.update().catch(()=>{});setInterval(()=>registration.update().catch(()=>{}),60000);});}
})();
</script>
